const criteria=new Set($json.criteria||[]); const restricted=$json.commercial_restrictions||[];
const map={
  tax_delinquent:{types:["tax_delinquency","tax_record","county_dataset"],fields:["delinquent_tax_amount","tax_status","tax_amount","parcel_id","owner_name"]},
  vacant:{types:["gis_parcel","property_record","tax_record","permit_record"],fields:["property_address","parcel_id","property_type","building_sqft","year_built","owner_name","mailing_address"]},
  vacant_land:{types:["gis_parcel","tax_record","zoning_record","county_dataset"],fields:["parcel_id","acreage","zoning","land_value","property_type","owner_name"]},
  absentee:{types:["property_record","tax_record","land_record"],fields:["owner_name","mailing_address","property_address","parcel_id"]},
  high_equity:{types:["land_record","property_record","tax_record"],fields:["owner_name","last_verified_sale_date","last_verified_sale_price","assessed_value","parcel_id"]},
  probate:{types:["probate_record","court_record","land_record"],fields:["owner_name","estate_or_probate_signal","property_address","parcel_id","source_record_id"]},
  pre_foreclosure:{types:["foreclosure_record","court_record","land_record"],fields:["owner_name","property_address","parcel_id","foreclosure_signal","source_record_id"]},
  fixer_upper:{types:["permit_record","code_enforcement","property_record","gis_parcel"],fields:["property_address","building_sqft","year_built","permit_records","condition_signals","parcel_id"]},
  distressed:{types:["tax_delinquency","foreclosure_record","permit_record","code_enforcement","property_record"],fields:["distress_signals","owner_name","property_address","parcel_id","source_record_id"]}
};
const selected=[...criteria].flatMap(c=>map[c]||[]).reduce((acc,v)=>acc.includes(v)?acc:acc.concat(v),[]);
const defaultTypes=["property_record","tax_record","gis_parcel","land_record"];
const sourceTypes=selected.length?selected:defaultTypes;
const requestedFields=[...criteria].flatMap(c=>map[c]?.fields||[]).reduce((acc,v)=>acc.includes(v)?acc:acc.concat(v),[]);
return [{json:{...$json,source_strategy:{criteria:[...criteria],priority_source_types:sourceTypes,required_evidence_fields:requestedFields,minimum_identity_fields:["owner_name","property_address","state"],curated_sources:$json.curated_sources||[],commercial_restrictions:restricted,source_resolution:$json.source_resolution||null,criteria_rules:{tax_delinquent:'Require explicit delinquent tax evidence; GIS alone is insufficient when no delinquency field exists.',vacant:'Require explicit structure/use evidence; absence of building data is not proof of vacancy.',vacant_land:'Prefer explicit land/vacant-land use plus structure evidence; acreage alone is not proof.',absentee:'Compare explicit site and mailing addresses; do not infer absentee status without both.',high_equity:'Do not call equity from assessed value alone; require explicit debt evidence or label as needs_evidence.',probate:'Require probate/court/estate evidence.',pre_foreclosure:'Require foreclosure/court/default/lis-pendens evidence.',fixer_upper:'Require explicit condition, permit, code-enforcement, violation, or comparable evidence.',distressed:'Require one or more explicit distress signals from tax, foreclosure, permit, code, or court sources.'},rules:["Use official sources first.","Match each criterion to evidence from the corresponding source type when available.","Do not infer a distress status from absence of data.","Keep unknown fields null and list them in limitations.","Preserve source_url or source_record_id for every candidate."]}}}];
